{"path": "src/riskscore/recency.py", "content": """"How long since the product and the account were last active."""
import numpy as np
import pandas as pd


def sku_last_trade(fit_df):
    return fit_df.groupby("sku")["placed_at"].max()


def account_last_order(fit_df):
    known = fit_df.dropna(subset=["account_id"])
    return known.groupby("account_id")["placed_at"].max()


def staleness(last_seen, fit_end):
    return (fit_end - last_seen).dt.days.astype("float64")


def add(df, sku_stale, account_stale, portfolio_stale):
    out = df.copy()
    out["f_sku_days_since_trade"] = out["sku"].map(sku_stale).fillna(
        portfolio_stale).astype("float64")
    out["f_account_days_since_order"] = out["account_id"].map(
        account_stale).fillna(-1.0).astype("float64")
    return out
"}

