import numpy as np
import pandas as pd


def sku_trade_days(fit_df):
    dates = fit_df["placed_at"].dt.normalize()
    return dates.groupby(fit_df["sku"]).nunique().astype("float64")


def account_gap(fit_df):
    known = fit_df.dropna(subset=["account_id"])
    dates = known["placed_at"].dt.normalize()

    def mean_gap(s):
        d = np.sort(s.unique())
        if len(d) < 2:
            return np.nan
        return float(np.diff(d).astype("timedelta64[D]").astype("float64").mean())

    gaps = dates.groupby(known["account_id"]).apply(mean_gap)
    portfolio = float(gaps.dropna().mean())
    return gaps, portfolio


def add(df, trade_days, gaps, portfolio_gap):
    out = df.copy()
    out["f_sku_trade_days"] = out["sku"].map(trade_days).fillna(0.0)
    out["f_account_order_gap"] = out["account_id"].map(gaps).fillna(portfolio_gap)
    return out
"}

