Lines priced unusually for their own sku are the ones that get sent back.
"""
import numpy as np
import pandas as pd


def price_dispersion(fit_df):
    def mad(s):
        return float((s - s.mean()).abs().mean())

    return fit_df.groupby("sku")["unit_price"].apply(mad).astype("float64")


def add(df, dispersion):
    out = df.copy()
    portfolio = float(dispersion.mean())
    out["f_sku_price_dispersion"] = out["sku"].map(dispersion).fillna(portfolio)
    return out
