"""
import numpy as np
import pandas as pd


class RateEncoder(object):

    def __init__(self, column, smoothing):
        self.column = column
        self.smoothing = float(smoothing)
        self.rates = None
        self.prior = None

    def fit(self, df, label):
        self.prior = float(df[label].mean())
        grp = df.groupby(self.column)[label]
        self.rates = ((grp.sum() + self.smoothing * self.prior)
                      / (grp.size() + self.smoothing)).astype("float64")
        return self

    def transform(self, df):
        return df[self.column].map(self.rates).fillna(self.prior).astype("float64")


def fit_all(fit_df, columns, smoothing, label):
    return [RateEncoder(column, smoothing).fit(fit_df, label) for column in columns]


def apply_all(df, encoders):
    out = df.copy()
    for enc in encoders:
        out["f_rate_%s" % enc.column] = enc.transform(out)
    return out
"}
